import Foundation

/// Home Interactor
/// Handles the business logic for Home module
final class HomeInteractor {
    
    // MARK: - Private Properties
    private let userService: UserService
    private let showService: ShowService

    // MARK: - Initialization
    init(userService: UserService = .shared, showService: ShowService = .shared) {
        self.userService = userService
        self.showService = showService
    }
}

// MARK: - HomeInteractorInterface Implementation

extension HomeInteractor: HomeInteractorInterface {
    func getShows(_ completion: @escaping ((Result<[Show], Error>) -> Void)) {
        showService.getShows(completion)
    }

    func logout() {
        userService.removeUser()
    }
}